mapper.select:
SELECT NOTIFICATION_ID AS notificationId, USER_ID AS userId, TYPE AS type, TARGET_TYPE AS targetType, TARGET_ID AS targetId, TITLE AS title, MESSAGE AS message, IS_READ AS isRead, CREATED_AT AS createdAt FROM NOTIFICATIONS WHERE USER_ID = #{userId} AND DELETED_AT IS NULL
AND NOTIFICATION_ID < #{cursorId}
ORDER BY NOTIFICATION_ID DESC LIMIT #{limit}
